#!/usr/bin/env bash
# =============================================================================
#  install.sh — ONE-SHOT AgentStack installer. Pre-ready, drop-in token.
#
#  Goal: a fresh user clones the repo, runs THIS, and the stack is ready.
#  No manual config hunting. Knowledge of the user's machine is auto-detected.
#
#  Usage (preferred — drop your token in, done):
#    ./install.sh --token sk-or-xxxxx           # one-shot, OpenRouter key
#    ./install.sh                                # interactive; prompts if missing
#
#  What it does (idempotent, safe):
#    1. Detect Hermes — install if missing
#    2. Detect OpenClaw — install if missing
#    3. Detect/init Obsidian vault
#    4. Write $HERMES_HOME/config.yaml from the repo template (no secrets)
#    5. Write $HERMES_HOME/.env, merging in the token if given
#    6. Link bridges + `stack` CLI into PATH
#    7. Install AgentStack skills into Hermes
#    8. Optionally install the Guardian-Web / security + vault plugins
#    9. Report exactly what's ready, what still needs a manual touch
#
#  Safe: idempotent, never chmod 777, never sudo pip, never commits secrets.
# =============================================================================
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
HERMES_HOME="${HERMES_HOME:-$HOME/AppData/Local/hermes}"
VAULT="${STACK_VAULT:-$HOME/Documents/Obsidian Vault}"
BIN_LINK_DIR="${BIN_LINK_DIR:-$HOME/bin}"

YELLOW=$'\e[33m'; GREEN=$'\e[32m'; CYAN=$'\e[36m'; RED=$'\e[31m'; RESET=$'\e[0m'
info(){ echo "${CYAN}==>${RESET} $*"; }
ok(){   echo "  ${GREEN}✓${RESET} $*"; }
warn(){ echo "  ${YELLOW}!${RESET} $*"; }
err(){  echo "  ${RED}x${RESET} $*"; }

TOKEN=""
while [ "$#" -gt 0 ]; do
  case "$1" in
    --token) TOKEN="${2:-}"; shift 2 ;;
    --vault) VAULT="$2"; shift 2 ;;
    *) shift ;;
  esac
done

detect_and_install_hermes() {
  info "1/8 Hermes (the brain)"
  local found=""
  [ -x "${HERMES_HOME}/hermes-agent/venv/Scripts/hermes.exe" ] && found=1
  [ -x "${HERMES_HOME}/venv/Scripts/hermes.exe" ] && found=1
  command -v hermes >/dev/null 2>&1 && found=1
  if [ -n "$found" ]; then
    ok "Hermes detected"
  else
    warn "Hermes not found — installing..."
    # require python
    if ! command -v python3 >/dev/null 2>&1 && ! command -v python >/dev/null 2>&1; then
      err "No Python found. Install Python 3.11+, then rerun."
      return 1
    fi
    (curl -fsSL https://hermes-agent.nousresearch.com/install.sh | bash) 2>&1 | tail -3 \
      && ok "Hermes installed" || err "Hermes install failed (see docs)"
  fi
}

detect_and_install_openclaw() {
  info "2/8 OpenClaw (the hands)"
  local found=""
  for c in "$APPDATA/npm/node_modules/openclaw/openclaw.mjs" \
           "$HOME/AppData/Roaming/npm/node_modules/openclaw/openclaw.mjs"; do
    [ -f "$c" ] && found="$c"
  done
  if [ -n "$found" ]; then
    ok "OpenClaw detected ($found)"
  else
    if command -v node >/dev/null 2>&1; then
      warn "OpenClaw not found — installing via npm (needs Node >=22)..."
      npm i -g openclaw 2>&1 | tail -2 && ok "OpenClaw installed" || err "npm install failed"
    else
      warn "Node not found — install Node LTS, then rerun."
    fi
  fi
}

detect_vault() {
  info "3/8 Obsidian vault (shared brain)"
  if [ -d "$VAULT" ]; then
    ok "Vault at $VAULT"
  else
    warn "No vault at $VAULT — creating it (open Obsidian, point it here)."
    mkdir -p "$VAULT"
    touch "$VAULT/AGENTS.md"
    ok "Vault scaffolded at $VAULT"
  fi
}

write_config() {
  info "4/8 Hermes config ($HERMES_HOME/config.yaml)"
  mkdir -p "$HERMES_HOME"
  if [ -f "$HERMES_HOME/config.yaml" ]; then
    ok "config.yaml exists — left untouched (preserves your settings)"
  else
    cp "$REPO_ROOT/config/hermes.config.yaml" "$HERMES_HOME/config.yaml"
    ok "wrote config.yaml from repo template"
  fi
}

write_env() {
  info "5/8 Hermes .env (secrets)"
  mkdir -p "$HERMES_HOME"
  local envf="$HERMES_HOME/.env"
  if [ -f "$envf" ]; then
    ok ".env exists — preserving your existing keys"
    # if a token was given and not already present, add it
    if [ -n "$TOKEN" ] && ! grep -q '^OPENROUTER_API_KEY=' "$envf"; then
      echo "OPENROUTER_API_KEY=$TOKEN" >> "$envf"
      ok "added OPENROUTER_API_KEY to existing .env"
    fi
  else
    if [ -n "$TOKEN" ]; then
      cat > "$envf" <<EOF
# Generated by AgentStack install.sh — fill/keep your secrets here.
# The installer already dropped in your OpenRouter token.
OPENROUTER_API_KEY=$TOKEN
TELEGRAM_BOT_TOKEN=
EOF
      ok "wrote .env with your OpenRouter token"
    else
      cp "$REPO_ROOT/config/hermes.env.example" "$envf"
      warn "No --token given — .env written. Add OPENROUTER_API_KEY and TELEGRAM_BOT_TOKEN."
    fi
  fi
}

link_bridges() {
  info "6/8 Linking stack + bridges into PATH ($BIN_LINK_DIR)"
  mkdir -p "$BIN_LINK_DIR"
  for src in "$REPO_ROOT/bin/stack" \
             "$REPO_ROOT/bin/stack.cmd" \
             "$REPO_ROOT/bridges/hermes-to-openclaw" \
             "$REPO_ROOT/bridges/hermes-worker" \
             "$REPO_ROOT/bridges/vault-note"; do
    [ -f "$src" ] || continue
    chmod +x "$src"
    local name; name="$(basename "$src")"
    ln -sf "$src" "$BIN_LINK_DIR/$name"
  done
  ok "bridges + stack linked to $BIN_LINK_DIR"
}

install_skills() {
  info "7/8 AgentStack skills -> Hermes"
  local dst="$HERMES_HOME/skills"
  mkdir -p "$dst"
  local n=0
  for sk in "$REPO_ROOT"/skills/learning/* "$REPO_ROOT"/skills/terminal/*; do
    [ -d "$sk" ] || continue
    local name; name="$(basename "$sk")"
    ln -sf "$sk" "$dst/$name" 2>/dev/null || cp -r "$sk" "$dst/$name"
    n=$((n+1))
  done
  ok "installed $n skills"
}

install_hooks() {
  info "8/8 Hooks + deployment"
  local hd="$HERMES_HOME/hooks"
  mkdir -p "$hd"
  if [ -d "$REPO_ROOT/hooks" ]; then
    for h in "$REPO_ROOT"/hooks/*; do
      [ -f "$h" ] || continue
      chmod +x "$h"
      ln -sf "$h" "$hd/$(basename "$h")"
    done
    ok "hooks linked to $hd"
  else
    ok "no hooks dir in repo"
  fi
}

# --- run -----------------------------------------------------------
detect_and_install_hermes || true
detect_and_install_openclaw || true
detect_vault
write_config
write_env
link_bridges
install_skills
install_hooks

echo
info "=== AgentStack install complete ==="
echo
ok "Run  stack status   to verify the stack"
echo
if [ -n "$TOKEN" ]; then
  ok "OpenRouter token dropped in. Telegram token: fill $HERMES_HOME/.env then  stack telegram on"
else
  warn "Token not provided. Add to: $HERMES_HOME/.env"
  printf '    %s\n' "OPENROUTER_API_KEY=sk-or-..."
  printf '    %s\n' "TELEGRAM_BOT_TOKEN=your-bot-token"
  echo
  echo "  Then:  stack telegram on   to go live over Telegram."
fi
echo
info "Pre-ready: config written, skills installed, bridges linked. Only your"
info "Telegram bot token (optional) and any extra provider keys are left."
